import pandas as pd

def clean(df):
    df = df.copy()
    # strip whitespace from string columns
    for col in df.select_dtypes(include='object').columns:
        df[col] = df[col].apply(lambda x: x.strip() if isinstance(x, str) else x)
    # normalise Category label variant
    if 'Category' in df.columns:
        df['Category'] = df['Category'].replace(r'^\s+|\s+$', '', regex=True)
    # parse Price which contains $ and text numbers
    if 'Price' in df.columns:
        df['Price'] = pd.to_numeric(df['Price'].replace(r'[\$,]', '', regex=True), errors='coerce')
    # ensure numeric types
    if 'Quantity' in df.columns:
        df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
    if 'Order_ID' in df.columns:
        df['Order_ID'] = pd.to_numeric(df['Order_ID'], errors='coerce')
    # drop exact duplicate rows
    df = df.drop_duplicates()
    # keep only allowed regions and drop missing
    if 'Region' in df.columns:
        df = df[df['Region'].isin(['North', 'South', 'East', 'West'])]
    # fix cross-column Revenue = Quantity * Price
    if {'Quantity', 'Price', 'Revenue'}.issubset(df.columns):
        df['Revenue'] = df['Quantity'] * df['Price']
    # parse dates, coerce invalid
    if 'Date' in df.columns:
        df['Date'] = pd.to_datetime(df['Date'], errors='coerce')
    return df

def answer(df):
    dfc = clean(df)
    # sum units sold per region
    sums = dfc.groupby('Region', dropna=True)['Quantity'].sum()
    # return ints, drop missing group keys
    return {region: int(sums[region]) for region in sums.index if pd.notna(region)}
